        left = [(r, c) for r in range(h) for c in range(divc)
                if grid[r][c] != bg]
        right = [(r, c) for r in range(h) for c in range(divc + 1, w)
                 if grid[r][c] != bg]
        points = left if left and not right else right if right and not left else []
