    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]

    # Vertical divider case.
    divc = next((c for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))
                 and grid[0][c] != bg), None)
    if divc is not None:
        left = [(r, c) for r in range(h) for c in range(divc) if grid[r][c] != bg]
        right = [(r, c) for r in range(h) for c in range(divc + 1, w) if grid[r][c] != bg]
        if right and not left:
            for r in range(h):
                out[r][max(c for _, c in right) + 1] = 8
        elif left and not right:
            # The demonstrated horizontal/object layouts put the stripe just
            # beyond the object's outer edge, away from the divider.
            for r in range(h):
                out[r][max(c for _, c in left) + 1] = 8
        return out

    # Horizontal divider case: sparse marker/object above or below.
    divr = next((r for r in range(h)
                 if all(v == grid[r][0] for v in grid[r])
                 and grid[r][0] != bg), None)
    if divr is not None:
