from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not seen[nr][nc]:
                seen[nr][nc] = True
                q.append((nr,nc))
    # Recolor only enclosed background pockets using the color of the enclosed center.
    pockets = [[(r,c) for r in range(h) for c in range(w) if grid[r][c] == 0 and not seen[r][c]]]
    centers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not centers:
        return out
    # The demos show a colored singleton/patch inside the frame; choose its color, not frame ink.
    from collections import Counter
    counts = Counter(grid[r][c] for r,c in centers)
    colors = sorted(counts, key=lambda color: counts[color])
    fill = colors[0]
    for pocket in pockets:
        if pocket:
            for r,c in pocket:
                out[r][c] = fill
    return out

