        for c in range(2,9): x[r][c]=4 if r in (2,3,8,9) or c in (2,3,7,8) else 5
    y=[row[:] for row in x]
    for r in range(13):
        for c in range(19):
            if x[r][c]==0 and 0<=r<12 and 0<=c<11: y[r][c]=5
    fixtures.append((x,y))
    for a,b in fixtures: assert transform(a)==b
