        r0,r1=min(r for r,c in pts),max(r for r,c in pts)
        c0,c1=min(c for r,c in pts),max(c for r,c in pts)
        if r1-r0>=2 and c1-c0>=2 and all(grid[r0][c]==col and grid[r1][c]==col for c in range(c0,c1+1)) and all(grid[r][c0]==col and grid[r][c1]==col for r in range(r0,r1+1)):
            frames.append((col,r0,r1,c0,c1))
    out=[[0]*w for _ in range(h)]
    for col,r0,r1,c0,c1 in frames:
        for c in range(c0,c1+1): out[r0][c]=out[r1][c]=col
        for r in range(r0,r1+1): out[r][c0]=out[r][c1]=col
