def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Divider lines are the all-8 rows/columns. The remaining intervals are cells.
    row_divs = [r for r in range(h) if all(v == 8 for v in g[r])]
    col_divs = [c for c in range(w) if all(g[r][c] == 8 for r in range(h))]
    row_ranges = []
    start = 0
    for d in row_divs + [h]:
        if start < d:
            row_ranges.append((start, d))
        start = d + 1
    col_ranges = []
    start = 0
    for d in col_divs + [w]:
        if start < d:
            col_ranges.append((start, d))
        start = d + 1
    marked_rows, marked_cols = set(), set()
    for i, (r0, r1) in enumerate(row_ranges):
        for j, (c0, c1) in enumerate(col_ranges):
            colors = {g[r][c] for r in range(r0, r1) for c in range(c0, c1)} - {0, 8}
            if 2 in colors:
                marked_cols.add(j)
            if 3 in colors:
                marked_rows.add(i)
    for i, (r0, r1) in enumerate(row_ranges):
        for j, (c0, c1) in enumerate(col_ranges):
            color = 6 if i in marked_rows and j in marked_cols else 3 if i in marked_rows else 2 if j in marked_cols else 0
            for r in range(r0, r1):
                for c in range(c0, c1):
                    g[r][c] = color
    return g

