def transform(grid):
    # Identify the uniform divider, then retain the panel on its right.
    h, w = len(grid), len(grid[0])
    if any(len(set(row)) == 1 for row in grid):
        r = next(r for r in range(h) if len(set(grid[r])) == 1)
        panel = grid[:r]
    else:
        c = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        panel = [row[c+1:] for row in grid]
    # In examples, the salient sparse color in the encoded panel becomes 3;
    # background becomes 4. For test's right panel the sparse color is 9.
    colors = set(x for row in panel for x in row)
    counts = {v: sum(x == v for row in panel for x in row) for v in colors}
    mark = min(colors, key=counts.get)
    return [[3 if x == mark else 4 for x in row] for row in panel]

def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_r = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_r is not None:
        a, b = grid[:sep_r], grid[sep_r+1:]
    else:
        sep_c = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        a = [row[:sep_c] for row in grid]
        b = [row[sep_c+1:] for row in grid]
    bg = min(set(x for row in a for x in row), key=lambda v: sum(x == v for row in a for x in row))
    return [[3 if x == y else bg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]

