def transform(grid):
    h, w = len(grid), len(grid[0])
    # The input panels are independent random patterns. Output is the cellwise
    # equality mask, using the background color of the panel that holds the
    # output background in the demonstrations (the right/bottom panel).
    sep_r = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_r is not None:
        first, second = grid[:sep_r], grid[sep_r+1:]
    else:
        sep_c = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        first = [row[:sep_c] for row in grid]
        second = [row[sep_c+1:] for row in grid]
    counts = {}
    for row in second:
